"""One serial session with an ELM327-compatible adapter (the OBDLink LX, D-019).

The adapter is a serial port: /dev/cu.* on the Mac, /dev/obd on the Pi. Over Bluetooth
SPP the baud rate is ignored, so any value works.
"""
import time

import serial

import obdlib

try:
    import termios
except ImportError:  # Windows has no termios; pyserial raises SerialException there.
    termios = None

# What a vanished port raises. On Linux a pty or RFCOMM tty whose other end has gone fails
# tcflush() with termios.error (EIO), which is not an OSError.
PORT_ERRORS = (serial.SerialException, OSError) + ((termios.error,) if termios else ())


class LinkLost(Exception):
    """The port vanished or errored: Bluetooth dropped, adapter unplugged or asleep."""


class Timeout(obdlib.AdapterError):
    """No prompt from the adapter within the timeout."""


# Seconds to wait for a timed-out request's late prompt before interrupting it.
RESYNC_WAIT = 0.5

# Settings sent after reset: echo off, no linefeeds, spaces on, headers off, auto protocol.
INIT = ("ATE0", "ATL0", "ATS1", "ATH0", "ATSP0")


class Adapter:
    def __init__(self, path, timeout=2.0, baud=115200):
        self.path, self.timeout = path, timeout
        self.banner = ""
        self.stale = False     # a request timed out; its reply may still be on its way
        try:
            # A write blocked on a stalled Bluetooth link must time out, or Ctrl-C could
            # never end the session; pyserial reports it as a SerialException (LinkLost).
            self.port = serial.Serial(path, baud, timeout=0.05, write_timeout=timeout)
        except (serial.SerialException, OSError) as e:
            raise LinkLost(f"cannot open {path}: {e}") from e

    @property
    def is_sim(self):
        """True when the adapter announced itself as obdsim. Its data is synth."""
        return "SIM" in self.banner.upper()

    def close(self):
        try:
            self.port.close()
        except (serial.SerialException, OSError):
            pass

    def _read_to_prompt(self, deadline):
        """Bytes up to and including the `>` prompt, or None at the deadline."""
        buf = b""
        while not buf.rstrip().endswith(b">"):
            if time.monotonic() > deadline:
                return None
            # Read what is waiting, or block for one byte, so the reply returns as soon as
            # its prompt arrives instead of at the end of a read timeout.
            buf += self.port.read(self.port.in_waiting or 1)
        return buf

    def _resync(self, cmd):
        """Wait out the reply to a request that timed out, so it is not read as the
        answer to the next one. First wait for its prompt; if none comes, send a bare CR,
        which makes a busy adapter stop (`STOPPED`, then `>`). A CR to an idle adapter
        would repeat the last command, which is why it is not sent first."""
        if self._read_to_prompt(time.monotonic() + min(RESYNC_WAIT, self.timeout)) is None:
            self.port.write(b"\r")
            if self._read_to_prompt(time.monotonic() + self.timeout) is None:
                raise Timeout(f"{cmd}: adapter still busy with a timed-out request")
        self.stale = False

    def command(self, cmd, timeout=None):
        """Send one command and return the raw reply text up to the `>` prompt."""
        try:
            if self.stale:
                self._resync(cmd)
            deadline = time.monotonic() + (timeout or self.timeout)
            self.port.reset_input_buffer()
            self.port.write(cmd.encode("ascii") + b"\r")
            buf = self._read_to_prompt(deadline)
            if buf is None:
                self.stale = True
                raise Timeout(f"{cmd}: no prompt after {timeout or self.timeout}s")
        except PORT_ERRORS as e:
            raise LinkLost(f"{cmd}: {e}") from e
        return buf.decode("ascii", errors="replace")

    def init(self):
        """Reset and configure the adapter. Returns the reset banner."""
        raw = self.command("ATZ", timeout=5.0)
        self.banner = " ".join(line for line in reply_lines(raw) if line != "ATZ")
        for cmd in INIT:
            self.command(cmd)
        # The first OBD request makes the adapter search for the protocol; allow for it.
        # With the ignition off that search fails (BusAsleep), and the caller waits.
        obdlib.check_bus(self.command("0100", timeout=15.0))
        return self.banner

    def query(self, mode, pid):
        """The data bytes of one request. Raises NoData, BusAsleep, AdapterError, Timeout,
        LinkLost."""
        return obdlib.parse_response(self.command(obdlib.request(mode, pid)), mode, pid)

    def query_all(self, mode, pid):
        """The data bytes of every line that answered one request, in arrival order: one
        per ECU that replied. Raises as query does."""
        return obdlib.parse_all(self.command(obdlib.request(mode, pid)), mode, pid)

    def supported_pids(self):
        """Every Mode 01 PID the ECU lists, walking 0x00, 0x20, ... while chained."""
        found, base = set(), 0x00
        while base <= 0xE0:
            # Every ECU that answers contributes; the engine may not answer first.
            raw = self.command(obdlib.request(1, base))
            try:
                block = obdlib.support_from_reply(raw, base)
            except obdlib.NoData:
                if base == 0x00:
                    raise           # nothing answers at all: the caller must know
                break               # a block the previous one chained to, unanswered
            found |= {p for p in block if p % 0x20}
            if base + 0x20 not in block:
                break
            base += 0x20
        return found

    def protocol(self):
        return " ".join(reply_lines(self.command("ATDP")))

    def voltage(self):
        return " ".join(reply_lines(self.command("ATRV")))

    def vin(self):
        return obdlib.decode_vin(self.command("0902", timeout=5.0))


def reply_lines(raw):
    """Clean reply lines, without the prompt."""
    return [line.strip() for line in raw.replace(">", "").replace("\n", "\r").split("\r")
            if line.strip()]
"""ELM327 / OBD-II Mode 01 and Mode 09 helpers shared by the tools.

Nothing here talks to a port. It parses adapter text, decodes the standard Mode 01 PIDs
(SAE J1979 formulas), turns support bitmaps into PID sets and handles the VIN. The logger,
the survey and the simulator all import it, so they agree on one reading of the protocol.
"""
import hashlib
import re


class AdapterError(Exception):
    """The adapter or the bus gave an answer we cannot use."""


class NoData(AdapterError):
    """The adapter answered `NO DATA`: the ECU did not reply to this request."""


class BusAsleep(AdapterError):
    """The adapter found no bus to talk on: ignition off, or the ECUs asleep. Not a fault
    of the adapter, so resetting it does not help; waiting does."""


# Replies that mean the adapter could not reach the bus at all.
_ASLEEP_TEXT = ("UNABLE TO CONNECT", "CAN ERROR")
# Replies that mean the request failed, as text the adapter prints.
_ERROR_TEXT = ("?", "BUFFER FULL", "STOPPED",
               "BUS BUSY", "BUS ERROR", "DATA ERROR", "<DATA ERROR", "FB ERROR",
               "LV RESET", "ACT ALERT", "BUS INIT: ...ERROR", "BUS INIT: ERROR",
               "BUS INIT:...ERROR", "ERROR")
# "BUS INIT: ...OK" is the ELM327's text after an ISO 9141 or KWP slow init; the
# spellings without the space are kept in case a clone prints them.
_SKIP_TEXT = ("SEARCHING...", "BUS INIT: ...OK", "BUS INIT: OK", "BUS INIT:...OK")
_HEX_LINE = re.compile(r"^(?:[0-9A-F]{2})+$")


def request(mode, pid):
    """The command text for a Mode request, e.g. request(1, 0x0C) is '010C'."""
    return f"{mode:02X}{pid:02X}"


def _lines(raw):
    """Reply text to clean upper-case lines: no prompt, no blanks, no NUL bytes."""
    out = []
    for line in re.split(r"[\r\n]+", raw.replace(">", "").replace("\x00", "")):
        line = line.strip().upper()
        if line:
            out.append(line)
    return out


def _hex_bytes(line):
    """A hex line, with or without spaces, as bytes; None if it is not hex."""
    packed = line.replace(" ", "")
    if _HEX_LINE.match(packed):
        return bytes.fromhex(packed)
    return None


def _check_text(line):
    if line == "NO DATA":
        raise NoData("NO DATA")
    if line in _ASLEEP_TEXT:
        raise BusAsleep(line)
    if line in _ERROR_TEXT:
        raise AdapterError(line)


def check_bus(raw):
    """Raise BusAsleep if a reply says the adapter could not reach the bus."""
    for line in _lines(raw):
        if line in _ASLEEP_TEXT:
            raise BusAsleep(line)


def parse_all(raw, mode, pid):
    """Data bytes of every line answering this request: one per ECU that replied.

    Raises NoData for `NO DATA` and AdapterError for any other failure, including a reply
    that holds no line for this request.
    """
    want = (mode + 0x40, pid)
    seen, found = False, []
    for line in _lines(raw):
        seen = True
        if line in _SKIP_TEXT:
            continue
        _check_text(line)
        data = _hex_bytes(line)
        if data is not None and len(data) >= 2 and (data[0], data[1]) == want:
            found.append(data[2:])
    if not found:
        raise AdapterError("no matching reply" if seen else "empty reply")
    return found


def parse_response(raw, mode, pid):
    """Data bytes of the first line answering this request (see parse_all).

    With headers off (ATH0) the lines do not say which ECU sent them, so a reading of one
    value takes the first answer. Support bitmaps must use support_from_reply instead.
    """
    return parse_all(raw, mode, pid)[0]


def _u16(d):
    return d[0] * 256 + d[1]


# pid: (name, unit, bytes needed, decode function over the data bytes)
PIDS = {
    0x04: ("Calculated engine load", "%", 1, lambda d: d[0] * 100 / 255),
    0x05: ("Coolant temperature", "degC", 1, lambda d: d[0] - 40),
    0x06: ("Short term fuel trim, bank 1", "%", 1, lambda d: (d[0] - 128) * 100 / 128),
    0x07: ("Long term fuel trim, bank 1", "%", 1, lambda d: (d[0] - 128) * 100 / 128),
    0x08: ("Short term fuel trim, bank 2", "%", 1, lambda d: (d[0] - 128) * 100 / 128),
    0x09: ("Long term fuel trim, bank 2", "%", 1, lambda d: (d[0] - 128) * 100 / 128),
    0x0A: ("Fuel pressure", "kPa", 1, lambda d: d[0] * 3),
    0x0B: ("Intake manifold pressure", "kPa", 1, lambda d: d[0]),
    0x0C: ("Engine speed", "rpm", 2, lambda d: _u16(d) / 4),
    0x0D: ("Vehicle speed", "km/h", 1, lambda d: d[0]),
    0x0E: ("Timing advance", "deg", 1, lambda d: d[0] / 2 - 64),
    0x0F: ("Intake air temperature", "degC", 1, lambda d: d[0] - 40),
    0x10: ("Mass air flow", "g/s", 2, lambda d: _u16(d) / 100),
    0x11: ("Throttle position", "%", 1, lambda d: d[0] * 100 / 255),
    0x1F: ("Run time since start", "s", 2, _u16),
    0x21: ("Distance with MIL on", "km", 2, _u16),
    0x2C: ("Commanded EGR", "%", 1, lambda d: d[0] * 100 / 255),
    0x2F: ("Fuel level", "%", 1, lambda d: d[0] * 100 / 255),
    0x30: ("Warm-ups since codes cleared", "count", 1, lambda d: d[0]),
    0x31: ("Distance since codes cleared", "km", 2, _u16),
    0x33: ("Barometric pressure", "kPa", 1, lambda d: d[0]),
    0x42: ("Control module voltage", "V", 2, lambda d: _u16(d) / 1000),
    0x43: ("Absolute load", "%", 2, lambda d: _u16(d) * 100 / 255),
    0x44: ("Commanded equivalence ratio", "ratio", 2, lambda d: _u16(d) / 32768),
    0x45: ("Relative throttle position", "%", 1, lambda d: d[0] * 100 / 255),
    0x46: ("Ambient air temperature", "degC", 1, lambda d: d[0] - 40),
    0x47: ("Absolute throttle position B", "%", 1, lambda d: d[0] * 100 / 255),
    0x49: ("Accelerator pedal position D", "%", 1, lambda d: d[0] * 100 / 255),
    0x4A: ("Accelerator pedal position E", "%", 1, lambda d: d[0] * 100 / 255),
    0x4C: ("Commanded throttle actuator", "%", 1, lambda d: d[0] * 100 / 255),
    0x5C: ("Engine oil temperature", "degC", 1, lambda d: d[0] - 40),
    0x5E: ("Engine fuel rate", "L/h", 2, lambda d: _u16(d) / 20),
}
# Narrow-band O2 sensors 0x14-0x1B report volts first (the short term trim is second).
for _pid in range(0x14, 0x1C):
    PIDS[_pid] = (f"O2 sensor {_pid - 0x13} voltage", "V", 2, lambda d: d[0] / 200)
# Wide-band O2 sensors 0x24-0x2B report the equivalence ratio first.
for _pid in range(0x24, 0x2C):
    PIDS[_pid] = (f"O2 sensor {_pid - 0x23} lambda", "ratio", 4,
                  lambda d: _u16(d) / 32768)
# Catalyst temperatures.
for _pid, _label in ((0x3C, "B1S1"), (0x3D, "B2S1"), (0x3E, "B1S2"), (0x3F, "B2S2")):
    PIDS[_pid] = (f"Catalyst temperature {_label}", "degC", 2, lambda d: _u16(d) / 10 - 40)


def pid_name(pid):
    entry = PIDS.get(pid)
    return entry[0] if entry else f"PID {pid:02X}"


def decode(pid, data):
    """(value, unit) for a Mode 01 reply's data bytes; (None, '') if unknown or short."""
    entry = PIDS.get(pid)
    if entry is None or len(data) < entry[2]:
        return (None, "")
    return (float(entry[3](data)), entry[1])


def support_pids(base, data):
    """The PIDs a support-bitmap reply (PID 0x00, 0x20, ...) lists as supported.

    The most significant bit is PID base+1 and the least significant is base+0x20, which
    says whether the next block exists.
    """
    if len(data) != 4:
        raise AdapterError(f"support bitmap needs 4 bytes, got {len(data)}")
    bits = int.from_bytes(data, "big")
    return {base + 1 + i for i in range(32) if bits & (1 << (31 - i))}


def support_from_reply(raw, base):
    """Every PID any answering ECU lists in a support-bitmap reply (PID 0x00, 0x20, ...)."""
    found = set()
    for data in parse_all(raw, 1, base):
        found |= support_pids(base, data)
    return found


def decode_vin(raw):
    """The VIN from a Mode 09 PID 02 reply, multi-frame or one frame per line."""
    chunks = {}
    framed = {}
    for line in _lines(raw):
        _check_text(line)
        m = re.match(r"^(\d+):\s*(.*)$", line)
        if m:
            data = _hex_bytes(m.group(2))
            index = int(m.group(1))
            if data is not None and index not in framed:
                framed[index] = data          # a repeated index is a second ECU: keep the first
            continue
        data = _hex_bytes(line)
        if data is not None and len(data) >= 3 and data[:2] == b"\x49\x02":
            chunks.setdefault(data[2], data[3:])   # first ECU's chunk per sequence number
    if framed:
        body = b"".join(framed[k] for k in sorted(framed))
        body = body[3:] if body[:2] == b"\x49\x02" else body
    elif chunks:
        body = b"".join(chunks[k] for k in sorted(chunks))
    else:
        raise AdapterError("no VIN in reply")
    vin = body.replace(b"\x00", b"").decode("ascii", errors="replace").strip()
    if not vin:
        raise AdapterError("empty VIN")
    return vin


def vin_hash(vin):
    """A short stable label that groups sessions by car without writing the VIN down.

    This is pseudonymization, not anonymity: a VIN has little entropy, so anyone holding
    candidate VINs can check them against it. It keeps the VIN out of files and git.
    """
    return hashlib.sha256(vin.encode("ascii")).hexdigest()[:12]

