/* Single-producer / single-consumer lock-free ring from capture (obdd) to storage
 * (storaged), its only consumer; analysis reads the committed log instead (D-031).
 * It is the handoff mechanism E's process boundary needs. It is not claimed as
 * mechanism F: Mode 01 rates never stress it, and no Pi-side sensor is added (D-029).
 *
 * The no-drop guarantee is the point. A gap in the record is a gap in the diagnosis,
 * so a drop must be impossible to hide: every slot carries a sequence number and the
 * consumer accounts for every one of them. If the ring is full the producer must
 * report the overrun rather than silently overwrite an unread sample.
 *
 * Layout is fixed so the ring can live in shared memory across the process boundary
 * that mechanism E requires.
 */
#ifndef CARWATCH_RING_H
#define CARWATCH_RING_H

#include <stdatomic.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define RING_CAPACITY 4096u   /* power of two — the mask depends on it */
#define RING_PAYLOAD    16u   /* bytes; a Mode 01 reply's data (<= 5 bytes) fits with room */

/* One sample, as its producer decoded it; storaged turns it into a D-034 sample record. */
typedef struct {
    uint64_t seq;                    /* set by ring_push: the slot's position, never reused */
    uint64_t mono_ns;                /* CLOCK_MONOTONIC at capture */
    uint8_t  mode;                   /* 0x01 for Mode 01; 0x00 for the box's own sensors (D-037) */
    uint8_t  pid;
    uint8_t  len;                    /* bytes of data[] in use */
    uint8_t  src;                    /* data_src_t — live | replay | synth; 0 is refused */
    float    value;                  /* the decoded value, in the PID's unit */
    uint8_t  data[RING_PAYLOAD];     /* the reply's raw data bytes */
} ring_slot_t;

#define RING_LINE    64u          /* cache line on the Pi 4's Cortex-A72 */
#define RING_MAGIC   0x474E5243u  /* the bytes "CRNG" */
#define RING_VERSION 3u           /* bump whenever ring_t or ring_slot_t changes layout */

/* Shared-memory names (D-039): obdd's ring and ambientd's (D-037). */
#define RING_NAME_OBD   "/carwatch-obd"
#define RING_NAME_PROBE "/carwatch-probe"

/* The header lets an attaching process refuse a ring written by a different build.
 * head and tail each own a cache line, so the producer's stores never invalidate the
 * line the consumer is spinning on, and the reverse. */
typedef struct {
    uint32_t magic;          /* RING_MAGIC */
    uint16_t version;        /* RING_VERSION */
    uint16_t slot_size;      /* sizeof(ring_slot_t) */
    uint32_t capacity;       /* RING_CAPACITY */
    uint64_t generation;     /* set once by ring_create: tells this ring from the next one */
    _Alignas(RING_LINE) _Atomic uint64_t head;      /* producer writes */
    _Alignas(RING_LINE) _Atomic uint64_t tail;      /* consumer writes */
    _Alignas(RING_LINE) _Atomic uint64_t overruns;  /* refused pushes — must stay zero */
    _Atomic uint64_t                     rejected;  /* unlabeled slots refused (D-040) */
    _Alignas(RING_LINE) ring_slot_t      slot[RING_CAPACITY];
} ring_t;

/* Initializes an unshared ring. Only the creator calls it (ring_create does). */
void     ring_init(ring_t *r);

/* True when r's header matches this build's layout. */
bool     ring_layout_ok(const ring_t *r);

/* Shared memory (src/ipc/shm.c, D-039). ring_create removes any stale object of that
 * name, makes a new one and initializes it: the supervisor calls it once at start.
 * ring_attach maps an existing ring and returns NULL, having logged why, if it is
 * missing, too small or of another layout: producers and storaged call it, and never
 * initialize. Every failure is logged with errno. */
ring_t  *ring_create(const char *name);
ring_t  *ring_attach(const char *name);
void     ring_detach(ring_t *r);
int      ring_destroy(const char *name);

/* Returns false when full (never overwriting an unread slot; counts an overrun) or when
 * the slot carries no valid src (counts a rejection, D-040). */
bool     ring_push(ring_t *r, const ring_slot_t *in);

/* Copies the i-th unread slot (0 is the oldest) without consuming it. Returns false when
 * fewer than i + 1 slots are unread. Consumer only. */
bool     ring_peek(const ring_t *r, size_t i, ring_slot_t *out);

/* Consumes the n oldest unread slots, freeing them for the producer. Returns false, and
 * consumes nothing, if fewer than n are unread. storaged calls it only after the batch
 * holding those slots is fsync'd, so a crash before that loses nothing (D-039).
 * Consumer only. */
bool     ring_release(ring_t *r, size_t n);

/* ring_peek(r, 0, out) then ring_release(r, 1). Returns false when empty. */
bool     ring_pop(ring_t *r, ring_slot_t *out);

uint64_t ring_overruns(const ring_t *r);
uint64_t ring_rejected(const ring_t *r);
size_t   ring_depth(const ring_t *r);

#endif
/* On-disk record format — mechanism D (D-034, with D-037 and D-040; extends 🔒 C.1, C.2).
 *
 * The constraint: power disappears at every key-off, and at any instant a cable is
 * pulled or a crank dips the supply, so every session can end mid-write; recovery must
 * find the torn tail and truncate it without losing anything before it.
 *
 * Therefore every record is (a) self-framing: a magic number to resynchronize on and a
 * length; and (b) CRC'd over everything before the CRC, so a partly written record is
 * detectable rather than merely wrong. Records are written in committed batches (D-025):
 * a batch with no COMMIT on disk is discarded at recovery.
 *
 * Layout (little-endian, the Pi's order): a 40-byte header, a body whose size depends
 * on its kind, then a CRC32 of header and body.
 */
#ifndef CARWATCH_RECORD_H
#define CARWATCH_RECORD_H

#include <float.h>
#include <stddef.h>
#include <stdint.h>

#define REC_MAGIC          0x31525743u   /* the bytes "CWR1" */
#define REC_HDR_SIZE       40u
#define REC_CRC_SIZE       4u
#define REC_EVENT_TEXT_MAX 200u
#define REC_MAX_BODY       (4u + REC_EVENT_TEXT_MAX)
#define REC_MAX_SIZE       (REC_HDR_SIZE + REC_MAX_BODY + REC_CRC_SIZE)

typedef enum {
    REC_SAMPLE   = 1,
    REC_BEGIN    = 2,
    REC_COMMIT   = 3,
    REC_BOOT     = 4,
    REC_SHUTDOWN = 5,
    REC_EVENT    = 6
} rec_kind_t;

#define REC_FLAG_WALL_UNTRUSTED 0x01u   /* the clock lost its backup this boot (D-030) */

typedef struct {
    uint32_t magic;      /* REC_MAGIC — resync anchor for the recovery scan */
    uint16_t kind;       /* rec_kind_t */
    uint16_t body_len;   /* bytes of body; each kind allows only its own size */
    uint64_t seq;        /* per log, never reused; a gap is a detected loss, not a hidden one */
    uint64_t mono_ns;    /* CLOCK_MONOTONIC: at capture for samples, at write otherwise */
    uint64_t wall_ns;    /* Unix time from the real-time clock (D-030) */
    uint8_t  src;        /* data_src_t: 1 live, 2 replay, 3 synth; 0 is invalid (D-040) */
    uint8_t  flags;      /* REC_FLAG_* */
    uint16_t reserved;   /* zero */
    uint32_t boot_id;    /* increments every boot; mono_ns compares only within one */
} rec_hdr_t;

/* Mode 0x00 is never sent to a car, so it names the box's own sensors (D-037). */
#define REC_MODE_BOX  0x00u
#define REC_PID_PROBE 0x01u   /* the DS18B20, value in °C */
#define REC_RAW_MAX   5u      /* the most data bytes a single-frame Mode 01 reply carries */

typedef struct {
    uint8_t mode;
    uint8_t pid;
    uint8_t raw_len;           /* 0 to REC_RAW_MAX */
    uint8_t raw[REC_RAW_MAX];  /* the reply's data bytes, kept beside the decoded value */
    float   value;
} rec_sample_t;

typedef struct { uint64_t txn_id; } rec_begin_t;

typedef struct {
    uint64_t txn_id;
    uint32_t records;    /* samples in the batch */
    uint32_t reserved;
} rec_commit_t;

typedef enum { REC_PREV_CLEAN = 0, REC_PREV_RECOVERED = 1, REC_PREV_FIRST = 2 } rec_prev_end_t;

typedef struct {
    uint8_t  prev_end;   /* rec_prev_end_t */
    uint8_t  reserved[3];
    uint32_t bytes_truncated;
    uint32_t records_lost;
} rec_boot_t;

typedef enum {
    REC_SHUT_SOURCE_LOST = 1,
    REC_SHUT_SIGNAL      = 2,
    REC_SHUT_OPERATOR    = 3
} rec_shutdown_reason_t;

typedef struct { uint8_t reason; uint8_t reserved[7]; } rec_shutdown_t;

/* On disk an event is 4 + len bytes: code, len, then len bytes of key=value text. */
typedef struct {
    uint16_t code;
    uint16_t len;
    char     text[REC_EVENT_TEXT_MAX];
} rec_event_t;

/* The layout is the file format: a change here is a format change (D-034). */
_Static_assert(__BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__, "the log is little-endian");
_Static_assert(sizeof(float) == 4 && FLT_MANT_DIG == 24, "sample values are IEEE f32");
_Static_assert(sizeof(rec_hdr_t) == REC_HDR_SIZE, "header is 40 bytes");
_Static_assert(offsetof(rec_hdr_t, kind) == 4 && offsetof(rec_hdr_t, body_len) == 6 &&
               offsetof(rec_hdr_t, seq) == 8 && offsetof(rec_hdr_t, mono_ns) == 16 &&
               offsetof(rec_hdr_t, wall_ns) == 24 && offsetof(rec_hdr_t, src) == 32 &&
               offsetof(rec_hdr_t, flags) == 33 && offsetof(rec_hdr_t, boot_id) == 36,
               "header offsets are D-034's");
_Static_assert(sizeof(rec_sample_t) == 12 && offsetof(rec_sample_t, value) == 8,
               "sample body is 12 bytes");
_Static_assert(sizeof(rec_begin_t) == 8, "begin body is 8 bytes");
_Static_assert(sizeof(rec_commit_t) == 16, "commit body is 16 bytes");
_Static_assert(sizeof(rec_boot_t) == 12, "boot body is 12 bytes");
_Static_assert(sizeof(rec_shutdown_t) == 8, "shutdown body is 8 bytes");
_Static_assert(offsetof(rec_event_t, text) == 4, "event text follows code and len");

typedef enum {
    REC_OK        =  0,
    REC_SHORT     = -1,   /* fewer bytes than the record needs: a torn tail, or not yet written */
    REC_BAD_MAGIC = -2,
    REC_BAD_KIND  = -3,
    REC_BAD_LEN   = -4,   /* body_len, or an event's len, that its kind does not allow */
    REC_BAD_CRC   = -5,
    REC_BAD_SRC   = -6    /* a CRC-valid record with no valid label: a writer bug */
} rec_status_t;

uint32_t rec_crc32(const void *buf, uint32_t len);

/* Writes magic, the header (kind, body_len and the rest from *hdr), the body and the CRC
 * into out. Returns the record's total size, or 0 if the header or body is invalid or
 * the record does not fit in cap. */
size_t rec_encode(uint8_t *out, size_t cap, const rec_hdr_t *hdr, const void *body);

/* Parses the record at buf[0, len). On REC_OK, fills *hdr, points *body into buf and sets
 * *size to the record's total length. Never reads past len. */
rec_status_t rec_decode(const uint8_t *buf, size_t len, rec_hdr_t *hdr,
                        const uint8_t **body, size_t *size);

const char *rec_status_name(rec_status_t st);

#endif
/* storaged — append-only, crash-consistent log. Mechanism D lives here.
 *
 * Drains the rings (obdd's, and ambientd's when it exists; D-031, D-037) into the
 * write-ahead log in batches: BEGIN, samples, COMMIT, one fsync, at 64 samples or one
 * second (D-025, D-035). A ring slot is released only after the batch holding it is
 * durable, so a kill -9 at any instant loses nothing (D-039).
 *
 *   storaged [--dir DIR] [--src live|replay|synth]
 *
 * --src labels storaged's own records (boot, shutdown, events); every sample keeps the
 * label its producer gave it. Exit codes: 0 after a clean stop, 1 if it cannot start.
 */
#include "common/log.h"
#include "ipc/ring.h"
#include "store/record.h"
#include "store/wal.h"

#include <errno.h>
#include <inttypes.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define HEARTBEAT_NS (3600ull * 1000000000ull)   /* hourly (handout §3.4) */
#define IDLE_NS      20000000L                   /* poll the rings every 20 ms when idle */

static volatile sig_atomic_t g_stop;

static void on_signal(int sig) { (void)sig; g_stop = 1; }

static int parse_src(const char *s, uint8_t *out)
{
    if (strcmp(s, "live") == 0)   { *out = SRC_LIVE;   return 0; }
    if (strcmp(s, "replay") == 0) { *out = SRC_REPLAY; return 0; }
    if (strcmp(s, "synth") == 0)  { *out = SRC_SYNTH;  return 0; }
    return -1;
}

typedef struct {
    const char *name;
    ring_t     *ring;
    size_t      taken;      /* slots in the open batch, released after it commits */
    bool        added;      /* the open batch holds a sample from this ring */
    uint64_t    last_seq;   /* ring seq of the newest slot taken */
    bool        skip;       /* D-039: slots up to skip_seq were committed before a restart */
    uint64_t    skip_seq;
} source_t;

/* Records which ring instance this run drains, so the next run can tell a ring that
 * outlived storaged from one made fresh at boot (D-039). */
static int note_generation(wal_t *w, unsigned ns, const ring_t *r)
{
    rec_event_t e;
    memset(&e, 0, sizeof e);
    e.code = WAL_EV_RING_GEN;
    int n = snprintf(e.text, sizeof e.text, "ns=%u gen=%" PRIx64, ns, r->generation);
    e.len = (uint16_t)n;
    return wal_add(w, REC_EVENT, w->src, wal_now_mono(), wal_now_wall(), &e,
