/* storaged's write-ahead log: mechanism D (D-025, D-034, D-035, D-041).
 *
 * Records go to the newest segment file, log-<first seq>.cwr, in batches: BEGIN, the
 * records, COMMIT, then one fsync. A batch counts only once its COMMIT is on disk. At
 * open, recovery scans the newest segment, keeps everything up to the last COMMIT and
 * truncates the rest (undo is truncation: nothing is ever overwritten, C.1), then writes
 * a boot batch saying whether the last session ended cleanly.
 */
#ifndef CARWATCH_WAL_H
#define CARWATCH_WAL_H

#include "store/record.h"

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define WAL_SEGMENT_BYTES   (16u * 1024u * 1024u)   /* D-034 */
#define WAL_BATCH_SAMPLES   64u                     /* D-035 */
#define WAL_BATCH_NS        1000000000ull           /* D-035: one second */
#define WAL_BUF_BYTES       (WAL_BATCH_SAMPLES * 56u + 32u * REC_MAX_SIZE)
#define WAL_NAMESPACES      2u    /* sample namespaces: 0 the car (Mode 01), 1 the box (D-037) */

/* Event codes storaged writes itself (D-042: sender byte 0x05). */
#define WAL_EV_RING_GEN     0x0501u   /* "ns=<0|1> gen=<hex>": which ring instance fed us */
#define WAL_EV_RING_SEQ     0x0502u   /* "ns=<0|1> seq=<hex>": last ring slot in this batch */

/* What a scan of one segment found. */
typedef struct {
    size_t   committed_len;       /* bytes up to and including the last COMMIT */
    bool     any_committed;
    bool     ended_clean;         /* the last committed batch ended with a SHUTDOWN */
    uint64_t last_seq, last_txn;
    uint32_t last_boot_id;
    uint32_t samples_committed;   /* in the whole segment */
    uint32_t records_lost;        /* decodable samples after the last COMMIT */
    uint64_t last_mono[WAL_NAMESPACES];   /* last committed sample's mono_ns, per namespace */
    uint64_t ring_gen[WAL_NAMESPACES];    /* last WAL_EV_RING_GEN, per namespace (0: none) */
    bool     has_ring_seq[WAL_NAMESPACES];
    uint64_t ring_seq[WAL_NAMESPACES];    /* last committed WAL_EV_RING_SEQ, per namespace */
} wal_scan_t;

typedef struct {
    char       dir[200];
    int        fd;
    uint64_t   seg_bytes;         /* committed length of the open segment */
    uint64_t   next_seq, next_txn;
    uint32_t   boot_id;
    uint8_t    src;               /* src of storaged's own records */
    uint8_t    flags;             /* REC_FLAG_* for every record this boot */
    wal_scan_t recovered;         /* what the scan at open found */
    rec_prev_end_t prev_end;
    uint64_t   truncated;         /* bytes the recovery at open cut off */
    bool       open_batch;
    uint64_t   batch_seq0;        /* next_seq before the open batch's BEGIN */
    uint64_t   batch_mono;        /* when the open batch began */
    uint32_t   batch_samples;
    size_t     len;
    uint8_t    buf[WAL_BUF_BYTES];
} wal_t;

/* Scans buf[0, len) as one segment. Never reads past len. */
void wal_scan(const uint8_t *buf, size_t len, wal_scan_t *out);

/* Opens (creating dir if needed) and recovers the newest segment, then commits a boot
 * batch. src labels storaged's own records. Returns 0, or -1 having logged why. */
int  wal_open(wal_t *w, const char *dir, uint8_t src, uint8_t flags);

/* Adds one record to the open batch, opening it with a BEGIN if needed. Returns 0, or -1
 * if the record is invalid or the batch is full (commit first). */
int  wal_add(wal_t *w, uint16_t kind, uint8_t src, uint64_t mono_ns, uint64_t wall_ns,
             const void *body, uint16_t body_len);

/* True when the open batch holds 64 samples or is a second old (D-035). */
bool wal_due(const wal_t *w, uint64_t now_mono_ns);

/* Appends COMMIT, writes the batch and fsyncs. Returns 0 once it is durable, or -1 having
 * logged why and cut the file back to its last commit; the batch is then discarded and
 * the caller must not release its ring slots. */
int  wal_commit(wal_t *w);

/* Commits any open batch, then a batch holding a SHUTDOWN record, and closes. */
int  wal_close(wal_t *w, rec_shutdown_reason_t reason);

uint64_t wal_now_mono(void);
uint64_t wal_now_wall(void);

#endif
/* Structured logging. Every line is machine-parseable, because the 48-hour soak log
 * is a graded deliverable and we will have to plot it. (handout §3.4) */
#ifndef CARWATCH_LOG_H
#define CARWATCH_LOG_H

#include <stdint.h>

typedef enum { LOG_DEBUG, LOG_INFO, LOG_WARN, LOG_ERROR, LOG_FATAL } log_level_t;

/* Data provenance. CLAUDE.md §2.7: replayed or synthesized data is labeled as such
 * EVERYWHERE it appears. This field exists from day one so that it is impossible to
 * forget later. Zero is not a label (D-040): memory nobody labeled reads as invalid,
 * never as live. */
typedef enum { SRC_INVALID = 0, SRC_LIVE = 1, SRC_REPLAY = 2, SRC_SYNTH = 3 } data_src_t;

#define SRC_IS_VALID(s) ((s) >= SRC_LIVE && (s) <= SRC_SYNTH)

void        log_init(const char *component, log_level_t min);
void        log_set_src(data_src_t src);
data_src_t  log_get_src(void);
const char *log_src_name(data_src_t src);

void log_emit(log_level_t lvl, const char *fmt, ...)
    __attribute__((format(printf, 2, 3)));

/* Hourly heartbeat: process liveness, RSS, cumulative event counts. Required by the
 * soak (handout §3.4) and the source of the RSS-vs-time plot in docs/EVALUATION.md §3. */
void log_heartbeat(uint64_t events, uint64_t drops);

#define LOG_D(...) log_emit(LOG_DEBUG, __VA_ARGS__)
#define LOG_I(...) log_emit(LOG_INFO,  __VA_ARGS__)
#define LOG_W(...) log_emit(LOG_WARN,  __VA_ARGS__)
#define LOG_E(...) log_emit(LOG_ERROR, __VA_ARGS__)

#endif
    return wal_add(w, REC_EVENT, w->src, wal_now_mono(), wal_now_wall(), &e,
                   (uint16_t)(4u + e.len));
}

/* Records, inside the batch, the newest ring slot it holds, so a run after a crash between
 * this batch's fsync and the ring release skips exactly what is durable (D-039). */
static int note_ring_seq(wal_t *w, unsigned ns, uint64_t seq)
{
    rec_event_t e;
    memset(&e, 0, sizeof e);
    e.code = WAL_EV_RING_SEQ;
    int n = snprintf(e.text, sizeof e.text, "ns=%u seq=%" PRIx64, ns, seq);
    e.len = (uint16_t)n;
    return wal_add(w, REC_EVENT, w->src, wal_now_mono(), wal_now_wall(), &e,
                   (uint16_t)(4u + e.len));
}

/* Moves unread slots of one ring into the open batch, up to the batch's sample cap. */
static uint64_t drain(wal_t *w, source_t *s)
{
    uint64_t added = 0;
    ring_slot_t slot;
    while (w->batch_samples < WAL_BATCH_SAMPLES && ring_peek(s->ring, s->taken, &slot)) {
        s->taken++;
        s->last_seq = slot.seq;
        if (s->skip && slot.seq <= s->skip_seq) continue;   /* durable before a restart */

        rec_sample_t r;
        memset(&r, 0, sizeof r);
        r.mode = slot.mode;
        r.pid = slot.pid;
        r.raw_len = slot.len < REC_RAW_MAX ? slot.len : (uint8_t)REC_RAW_MAX;
        memcpy(r.raw, slot.data, r.raw_len);
        r.value = slot.value;
        uint64_t now_mono = wal_now_mono(), now_wall = wal_now_wall();
        uint64_t age = now_mono > slot.mono_ns ? now_mono - slot.mono_ns : 0;
        if (wal_add(w, REC_SAMPLE, slot.src, slot.mono_ns, now_wall - age, &r, sizeof r) != 0) {
            /* Full or invalid: leave the slot for after the commit. */
            s->taken--;
            s->last_seq = slot.seq - 1;
            LOG_W("sample_not_added ring=%s seq=%" PRIu64 " src=%u", s->name, slot.seq,
                  (unsigned)slot.src);
            break;
        }
        added++;
        s->added = true;
    }
    return added;
}

int main(int argc, char **argv)
{
    const char *dir = "/var/lib/carwatch/log";
    uint8_t src = SRC_LIVE;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--dir") == 0 && i + 1 < argc) {
            dir = argv[++i];
        } else if (strcmp(argv[i], "--src") == 0 && i + 1 < argc &&
                   parse_src(argv[i + 1], &src) == 0) {
            i++;
        } else {
            fprintf(stderr, "usage: storaged [--dir DIR] [--src live|replay|synth]\n");
            return 1;
        }
    }

    log_init("storaged", LOG_INFO);
    log_set_src((data_src_t)src);
    LOG_I("start format=CWR1 dir=%s", dir);

    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = on_signal;
    if (sigemptyset(&sa.sa_mask) != 0 || sigaction(SIGTERM, &sa, NULL) != 0 ||
        sigaction(SIGINT, &sa, NULL) != 0) {
        LOG_E("sigaction_failed errno=%d (%s)", errno, strerror(errno));
        return 1;
    }

    int rc = 1;
    wal_t *w = NULL;
    source_t srcs[WAL_NAMESPACES] = {
        { .name = RING_NAME_OBD },
        { .name = RING_NAME_PROBE },
    };

    srcs[0].ring = ring_attach(RING_NAME_OBD);
    if (srcs[0].ring == NULL) goto out;        /* the supervisor makes it; it retries us */
    srcs[1].ring = ring_attach(RING_NAME_PROBE);
    if (srcs[1].ring == NULL) LOG_W("probe_ring_absent name=%s", RING_NAME_PROBE);

    w = malloc(sizeof *w);
    if (w == NULL) {
        LOG_E("alloc_failed bytes=%zu", sizeof *w);
        goto out;
    }
    if (wal_open(w, dir, src, 0) != 0) goto out;

    for (unsigned ns = 0; ns < WAL_NAMESPACES; ns++) {
        if (srcs[ns].ring == NULL) continue;
        if (w->recovered.ring_gen[ns] == srcs[ns].ring->generation &&
            w->recovered.has_ring_seq[ns]) {
            srcs[ns].skip = true;
            srcs[ns].skip_seq = w->recovered.ring_seq[ns];
        }
        if (note_generation(w, ns, srcs[ns].ring) != 0 || wal_commit(w) != 0) goto out;
    }
    LOG_I("draining prev_end=%u skip_obd=%d/%" PRIu64 " skip_probe=%d/%" PRIu64,
          (unsigned)w->prev_end, (int)srcs[0].skip, srcs[0].skip_seq, (int)srcs[1].skip,
          srcs[1].skip_seq);

    uint64_t samples = 0;
    uint64_t next_beat = wal_now_mono();
    while (!g_stop) {
        uint64_t added = 0;
        for (unsigned ns = 0; ns < WAL_NAMESPACES; ns++)
            if (srcs[ns].ring != NULL) added += drain(w, &srcs[ns]);

        bool any_taken = srcs[0].taken > 0 || srcs[1].taken > 0;
        if (wal_due(w, wal_now_mono()) || (any_taken && !w->open_batch)) {
            int noted = 0;
            for (unsigned ns = 0; ns < WAL_NAMESPACES; ns++)
                if (srcs[ns].added) noted |= note_ring_seq(w, ns, srcs[ns].last_seq);
            if (noted != 0 || wal_commit(w) != 0) {
                /* The batch is gone from the log but not from the rings: start again. */
                srcs[0].taken = srcs[1].taken = 0;
                srcs[0].added = srcs[1].added = false;
                struct timespec back = { 1, 0 };
                (void)nanosleep(&back, NULL);
                continue;
            }
            for (unsigned ns = 0; ns < WAL_NAMESPACES; ns++) {
                if (srcs[ns].ring != NULL && srcs[ns].taken > 0 &&
                    !ring_release(srcs[ns].ring, srcs[ns].taken))
                    LOG_E("ring_release_failed ring=%s n=%zu", srcs[ns].name, srcs[ns].taken);
                srcs[ns].taken = 0;
                srcs[ns].added = false;
            }
        }
        samples += added;

        uint64_t now = wal_now_mono();
        if (now >= next_beat) {
            uint64_t over = ring_overruns(srcs[0].ring) +
                            (srcs[1].ring != NULL ? ring_overruns(srcs[1].ring) : 0);
            log_heartbeat(samples, over);
            next_beat = now + HEARTBEAT_NS;
        }
        if (added == 0) {
            struct timespec idle = { 0, IDLE_NS };
            (void)nanosleep(&idle, NULL);
        }
    }

    /* Clean stop: make the open batch durable, free its slots, and mark the end. */
    for (unsigned ns = 0; ns < WAL_NAMESPACES; ns++)
        if (srcs[ns].added && note_ring_seq(w, ns, srcs[ns].last_seq) != 0)
            LOG_E("ring_seq_note_failed ring=%s", srcs[ns].name);
    if (wal_commit(w) == 0)
        for (unsigned ns = 0; ns < WAL_NAMESPACES; ns++)
            if (srcs[ns].ring != NULL && srcs[ns].taken > 0)
                (void)ring_release(srcs[ns].ring, srcs[ns].taken);
    rc = wal_close(w, REC_SHUT_SIGNAL) == 0 ? 0 : 1;
    LOG_I("stop samples=%" PRIu64 " clean=%d", samples, rc == 0);

out:
    if (rc != 0) LOG_E("exit status=1");
    free(w);
    for (unsigned ns = 0; ns < WAL_NAMESPACES; ns++) ring_detach(srcs[ns].ring);
    return rc;
}
