static void *producer(void *arg)
{
    (void)arg;
    for (uint64_t i = 0; i < CONCURRENT_N; ) {
        ring_slot_t s = mk(i);
        memcpy(s.data, &i, sizeof i);
        if (ring_push(g_ring, &s)) i++;
