    uint32_t got = rec_crc32(v, (uint32_t)strlen(v));
    if (got != 0xCBF43926u) {
        fprintf(stderr, "  FAIL crc32(\"123456789\") = 0x%08X, want 0xCBF43926\n", got);
        failures++;
