{
    lines_t it = { raw, raw + len };
    line_t l;
    while (next_line(&it, &l))
        if (!l.too_long && in_list(l.text, k_asleep, COUNT(k_asleep))) return OBD_ASLEEP;
    return OBD_OK;
}

