    return obd_decode(pid, d, n, &v) && fabs(v - want) < 1e-9;
}

static void test_decode(void)
{
    static const uint8_t rpm[] = { 0x1A, 0xF8 };
    CHECK(decodes(0x0C, rpm, 2, 1726.0) && strcmp(obd_pid_unit(0x0C), "rpm") == 0, "rpm");
