/* A write blocked on a stalled Bluetooth link must time out, as elm.py's write_timeout. */
static elm_status_t write_all(elm_t *e, const char *s, size_t len, int64_t deadline)
{
    while (len > 0) {
        ssize_t n = write(e->fd, s, len);
        if (n > 0) {
            s += n;
            len -= (size_t)n;
            continue;
