            /* Mid-stream, with a batch likely open: the supervisor's view of a crash. */
            CHECK(kill(pid, SIGKILL) == 0, "kill -9 storaged");
            int st;
            CHECK(waitpid(pid, &st, 0) == pid && WIFSIGNALED(st), "storaged died");
