    ring_detach(obd);
    ring_detach(probe);
    (void)ring_destroy(RING_NAME_OBD);
    (void)ring_destroy(RING_NAME_PROBE);
    remove_dir(dir);
    return failures == 0 ? 0 : 1;
}

