# labeled replay, a synth one synth; SPEED divides the recorded spacing.
SPEED ?= 1
replay: all
	@test -n "$(FIX)" || { echo "usage: make replay FIX=<capture>.jsonl [SPEED=n]"; exit 1; }
	CARWATCH_BIN=$(BIN) scripts/replay.sh $(FIX) $(SPEED)

